"""Regenerate the synthetic form-field fixture.

The committed ``session_1_evals.pdf`` is a Swim Ontario On-Deck Evaluation
form filled in with **entirely synthetic** names and clubs generated by
`Faker <https://faker.readthedocs.io/>`_ with a fixed seed. No real
person's information is ever committed.

For reproducibility we record the exact command used to regenerate the
committed fixture:

.. code-block:: bash

    python tests/fixtures/form_field/make_synthetic_fixture.py \\
        --seed 42 \\
        --pages 2 \\
        --officials-on-last-page 2

Running with the same seed (and same Faker version) produces an
identical PDF. If you bump Faker majorly and the output drifts, update
this docstring's recorded command and the assertions in
``tests/test_form_extract.py`` that reference specific synthetic names.

Inputs:
    The blank Swim Ontario eval_form.pdf, located by default at
    ``../../eval-gen/eval_form.pdf`` relative to this repo. Swim Ontario
    publishes the form publicly; the blank contains no PII.

Outputs:
    Overwrites ``session_1_evals.pdf`` in this directory.
"""
from __future__ import annotations

import argparse
import re
import sys
from itertools import cycle
from pathlib import Path

import fitz
from faker import Faker


# ---------------------------------------------------------------------------
# Constrained vocabularies — these are intentionally not randomised.
# Faker doesn't know swimming roles or club codes, and tests benefit from
# coverage of every position the parser will see in the wild.
# ---------------------------------------------------------------------------

POSITIONS = [
    "Starter",
    "Stroke Judge",
    "Inspector of Turns",
    "Inspector of Turns",
    "Chief Timer",
    "Timer",
    "Timer",
    "Admin Desk",
    "Recorder",
    "Timer",
    "Timer",
]

# Some rows have lane assignments, some don't (matches the real-world
# pattern where only certain positions get a lane).
LANE_BY_POSITION = {
    "Inspector of Turns": cycle(["4", "5", "6", "7"]),
    "Timer":              cycle(["1", "2", "3", "4", "5", "6", "7", "8"]),
}


ROWS_PER_PAGE = 9
DUPLICATE_SUFFIX_RE = re.compile(r"\s\[\d+\]$")


def _make_officials(faker: Faker, n: int) -> list[dict[str, str]]:
    out: list[dict[str, str]] = []
    for i in range(n):
        position = POSITIONS[i % len(POSITIONS)]
        lane_iter = LANE_BY_POSITION.get(position)
        lane = next(lane_iter) if lane_iter is not None else ""
        out.append({
            "name":     faker.name(),
            # Club codes are 3 upper-case letters (Swim Ontario convention).
            "club":     faker.bothify(text="???", letters="ABCDEFGHIJKLMNOPQRSTUVWXYZ"),
            "position": position,
            "lane":     lane,
        })
    return out


def _meet_header(faker: Faker, total_pages: int) -> dict[str, str]:
    # Anchor the date arbitrarily so the fixture isn't different every year.
    return {
        "Competition Name":        f"{faker.last_name()} Open 2026",
        "Competition Coordinator": faker.name(),
        # cc_level (the meet-level "Level" widget) is intentionally blank —
        # it's a free-text field on the form that evaluators don't always
        # fill in, and a blank value is itself worth testing.
        "Level":                   "",
        "Date  Session":           "Fri, Jan 9, 2026 / Session 1",
        # Host club is a known 3-letter code; reuse Faker for variety.
        "Host Club":               faker.bothify(text="???", letters="ABCDEFGHIJKLMNOPQRSTUVWXYZ"),
        "COC":                     faker.name(),
        "Page":                    "",  # set per page below
        "of":                      str(total_pages),
    }


def _blank_row_values() -> dict[str, str]:
    return {
        "Name of OfficialRow":                             "",
        "ClubRow":                                         "",
        "PositionRow":                                     "",
        "Lane numberRow":                                  "",
        "How many times have you worked this positionRow": "",
        "Mentor Official  Session refereeRow":             "",
        "LevelRow":                                        "",
        "Successful initialRow":                           "",
    }


def _row_values(o: dict[str, str]) -> dict[str, str]:
    return {
        "Name of OfficialRow":                             o["name"],
        "ClubRow":                                         o["club"],
        "PositionRow":                                     o["position"],
        "Lane numberRow":                                  o["lane"],
        "How many times have you worked this positionRow": "",
        "Mentor Official  Session refereeRow":             "",
        "LevelRow":                                        "",
        "Successful initialRow":                           "",
    }


def _write_widget(widget, value: str) -> None:
    widget.field_value = value
    widget.update()


def generate(
    template_path: Path,
    output_path: Path,
    seed: int,
    pages: int,
    officials_on_last_page: int,
) -> None:
    faker = Faker("en_CA")
    Faker.seed(seed)

    total_officials = (pages - 1) * ROWS_PER_PAGE + officials_on_last_page
    officials = _make_officials(faker, total_officials)
    meet = _meet_header(faker, total_pages=pages)

    pages_of_officials = [
        officials[i : i + ROWS_PER_PAGE]
        for i in range(0, len(officials), ROWS_PER_PAGE)
    ]

    # eval-gen's blank eval_form.pdf is single-page. We mirror eval-gen's
    # own pattern: open the template fresh for each page, fill its widgets
    # in isolation, then insert that filled single-page document into the
    # combined output. Filling a freshly-opened template ensures every
    # page's widgets are independent — PyMuPDF's AcroForm handling will
    # otherwise share field values by name across pages of the same doc,
    # so a single multi-page open + fill ends up with later pages blank.
    output = fitz.open()
    for page_index in range(pages):
        page_officials = pages_of_officials[page_index]
        page_meet = dict(meet)
        page_meet["Page"] = str(page_index + 1)

        template = fitz.open(template_path)
        page = template[0]
        for widget in page.widgets() or ():
            # Strip PyMuPDF's `` [NNN]`` duplicate-widget suffix so we can
            # match against bare widget names. (Bare names only on a
            # freshly-opened single-page template — but cheap to guard.)
            bare = DUPLICATE_SUFFIX_RE.sub("", widget.field_name)

            if bare in page_meet:
                _write_widget(widget, page_meet[bare])
                continue

            m = re.match(r"^(.+?)Row(\d+)$", bare)
            if not m:
                continue
            base, row_index = m.group(1), int(m.group(2))
            base_key = f"{base}Row"

            if row_index <= len(page_officials):
                row_vals = _row_values(page_officials[row_index - 1])
            else:
                row_vals = _blank_row_values()
            _write_widget(widget, row_vals.get(base_key, ""))

        output.insert_pdf(template, from_page=0, to_page=0)
        template.close()

    output.save(output_path, deflate=True, garbage=4, clean=True)
    output.close()


def _default_template_path() -> Path:
    """Best-effort guess at where the blank eval_form.pdf lives locally."""
    candidates = [
        Path(__file__).resolve().parents[3].parent / "eval-gen" / "eval_form.pdf",
        Path("C:/Users/gavbe/src/eval-gen/eval_form.pdf"),
    ]
    for c in candidates:
        if c.is_file():
            return c
    raise FileNotFoundError(
        "Could not find eval-gen/eval_form.pdf. Either clone "
        "https://github.com/gavinbee/eval-gen alongside this repo, or "
        "pass --template /path/to/eval_form.pdf"
    )


def _parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    p.add_argument(
        "--template",
        type=Path,
        default=None,
        help="Path to the blank Swim Ontario eval_form.pdf. "
             "Defaults to eval-gen/eval_form.pdf next to this repo.",
    )
    p.add_argument(
        "--output",
        type=Path,
        default=Path(__file__).parent / "session_1_evals.pdf",
        help="Output path for the synthetic fixture.",
    )
    p.add_argument(
        "--seed",
        type=int,
        default=42,
        help="Faker seed. Re-running with the same seed and same Faker "
             "version produces an identical PDF.",
    )
    p.add_argument(
        "--pages",
        type=int,
        default=2,
        help="Number of pages in the output.",
    )
    p.add_argument(
        "--officials-on-last-page",
        type=int,
        default=2,
        help="How many of the 9 row slots on the last page to fill.",
    )
    return p.parse_args()


def main() -> int:
    args = _parse_args()
    template = args.template or _default_template_path()
    print(f"Reading template: {template}")
    print(f"Writing fixture:  {args.output}")
    print(f"Seed:             {args.seed}")
    generate(
        template_path=template,
        output_path=args.output,
        seed=args.seed,
        pages=args.pages,
        officials_on_last_page=args.officials_on_last_page,
    )
    print("Done.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
